using NUnit.Framework; using System.Collections.Generic; using AcadeGameMaker.Costumes; using AcadeGameMaker.Presentation;
namespace AcadeGameMaker.Tests.EditMode.Presentation { public sealed class CostumePresentationV1Tests { const string H="0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
[Test] public void AC_COST_005_And_007_BindingIsWholeAndClipGated(){var d=new CostumeDefinitionV1("seryeong","seryeong.costume.one.v1","one",H,"reference-hair",CostumeDisposition.Accepted,true,"seryeong.costume.one.v1.portrait.v1","seryeong.costume.one.v1.atlas.v1",H,H,H,3);var c=new CostumeCatalogV1(4,new[]{d});Assert.That(CostumePresentationServiceV1.TryCreateBinding(c,"seryeong",d.CostumeId,4,3,new[]{"seryeong.action.idle.v1"},out var b),Is.EqualTo(CostumeBindingRejection.None));var s=new CompletedActorSnapshotV1(8,"seryeong","seryeong.action.idle.v1",500,"east",12,13);Assert.That(CostumePresentationServiceV1.TrySwap(b,b,s,out _),Is.EqualTo(CostumeBindingRejection.None));Assert.That(CostumePresentationServiceV1.TrySwap(b,b,new CompletedActorSnapshotV1(8,"seryeong","seryeong.action.draw.v1",500,"east",12,13),out _),Is.EqualTo(CostumeBindingRejection.MissingClip));}
[Test] public void AC_COST_009_PendingPreviewCannotPrepareSelection(){var c=CostumeCatalogV1.SeryeongInventoryPending();var v=CostumePresentationServiceV1.BuildViews(c,new CostumeStateV1(0,new string[0],new KeyValuePair<string,string>[0]),"seryeong")[0];Assert.That(v.CanPrepareSelection,Is.False);}}
}
